const c=[{minimo:3,chave:"alta",rotulo:"Alta demanda",descricao:"Curso muito procurado no estado."},{minimo:1.5,chave:"media",rotulo:"Demanda média",descricao:"Procura equilibrada com o número de vagas."},{minimo:0,chave:"baixa",rotulo:"Baixa demanda",descricao:"Costuma ter vaga para quase todos os inscritos."}];function u(a){return c.find(r=>a>=r.minimo)}function d(a){return a.toLocaleString("pt-BR",{minimumFractionDigits:1,maximumFractionDigits:1})}function l(a){const r=(a?.historico||[]).filter(o=>o?.periodo&&o.vagas>0).map(o=>{const[e,m]=o.periodo.split("-").map(Number),s=o.inscritos/o.vagas;return{...o,ano:e,semestre:m,porVaga:s,porVagaTexto:d(s)}}).sort((o,e)=>o.periodo.localeCompare(e.periodo));if(!r.length)return null;const t=r.filter(o=>o.semestre===1),i=t.length?t:r,n=i[i.length-1];return{...n,nivel:u(n.porVaga),serie:i}}export{l as r};
